@app.cell
def model_helpers(np):
    # Ages 2 and 80 are the boundary knots. Internally age is rescaled to
    # u = (age - 41) / 39, which runs from -1 to 1. This only keeps the numbers
    # small; it does not change the fitted curves.
    LOW, HIGH = 2.0, 80.0

    def scale(x):
        """Rescale age in years to u in [-1, 1] on the observed range."""
        return (np.asarray(x, dtype=float) - 41.0) / 39.0

    def quantile_knots(ages, count: int) -> np.ndarray:
        """Interior knots at equally spaced quantiles of age, as bs() and ns() do."""
        if count == 0:
            return np.array([])
        probs = np.arange(1, count + 1) / (count + 1)
        return np.unique(np.quantile(ages, probs))

    def spline_columns(u, degree: int, c: np.ndarray, derivative: int = 0):
        """Powers of u and one truncated power (u - c)_+^d per knot, or their derivatives."""
        u = np.atleast_1d(np.asarray(u, dtype=float))
        cols = []
        for j in range(degree + 1):
            if j < derivative:
                cols.append(np.zeros_like(u))
            else:
                factor = (
                    np.prod(np.arange(j - derivative + 1, j + 1)) if derivative else 1
                )
                cols.append(factor * u ** (j - derivative))
        for k in c:
            if derivative > degree:
                cols.append(np.zeros_like(u))
            else:
                factor = (
                    np.prod(np.arange(degree - derivative + 1, degree + 1))
                    if derivative
                    else 1
                )
                power = degree - derivative
                # (u - k)_+^0 is a step: 0 before the knot, 1 after (numpy gives 0**0 = 1).
                hinge = (
                    (u > k).astype(float)
                    if power == 0
                    else np.maximum(u - k, 0.0) ** power
                )
                cols.append(factor * hinge)
        return np.column_stack(cols)

    NATURAL_DEGREES = (3,)

    def natural_null_space(degree: int, c: np.ndarray) -> np.ndarray:
        """Combinations of spline columns for a natural spline of odd degree d = 2m - 1.

        Beyond the boundary knots a natural spline is a polynomial of degree m - 1
        (a straight line for the cubic, d = 3), joined as smoothly as at the interior
        knots. That requires derivatives m to d - 1 to be zero at ages 2 and 80: for
        d = 3, zero curvature. Keeping the column combinations in the null space of
        these constraints turns K + 4 columns into K + 2, as in R's ns().
        """
        m = (degree + 1) // 2
        rows = np.vstack(
            [
                spline_columns(edge, degree, c, derivative=j)[0]
                for j in range(m, degree)
                for edge in (-1.0, 1.0)
            ]
        )
        _, s, vt = np.linalg.svd(rows)
        rank = int(np.sum(s > 1e-10))
        return vt[rank:].T

    def design_matrix(x, degree: int, knots: np.ndarray, kind: int) -> np.ndarray:
        """Columns for model 1-5: polynomial, piecewise (two ways), spline, natural spline."""
        u = scale(x)
        c = scale(knots)
        powers = np.polynomial.polynomial.polyvander(u, degree)
        if kind == 0:
            return powers
        if kind == 1:
            regions = np.searchsorted(c, u, side="right")
            return np.column_stack(
                [powers * (regions == r)[:, None] for r in range(len(c) + 1)]
            )
        if kind == 2:
            return np.column_stack([powers] + [powers * (u >= k)[:, None] for k in c])
        if kind == 3:
            if degree == 0:
                raise ValueError("Choose degree 1-3 for a regression spline.")
            return spline_columns(u, degree, c)
        if kind == 4:
            if degree not in NATURAL_DEGREES:
                raise ValueError("Natural splines are shown for d = 3 only.")
            null = natural_null_space(degree, c)
            inside = spline_columns(np.clip(u, -1.0, 1.0), degree, c)
            # Beyond each boundary: Taylor polynomial of degree m - 1 at the boundary
            # (a straight line for the natural cubic).
            m = (degree + 1) // 2
            for edge, mask in ((-1.0, u < -1.0), (1.0, u > 1.0)):
                if mask.any():
                    dist = u[mask] - edge
                    tail = np.zeros((mask.sum(), inside.shape[1]))
                    for j in range(m):
                        derivative = spline_columns(edge, degree, c, derivative=j)[0]
                        tail += np.outer(
                            dist**j / np.prod(np.arange(1, j + 1)), derivative
                        )
                    inside[mask] = tail
            return inside @ null
        raise ValueError(f"Unknown model kind: {kind}")

    def fit_models(x, y, degree: int, knots: np.ndarray) -> dict:
        """Least-squares fits of models 1-5; None where a model is not defined."""
        results = {}
        for kind in range(5):
            if (kind == 3 and degree == 0) or (
                kind == 4 and degree not in NATURAL_DEGREES
            ):
                results[kind] = None
                continue
            matrix = design_matrix(x, degree, knots, kind)
            beta, _, rank, _ = np.linalg.lstsq(matrix, y, rcond=None)
            # A piecewise polynomial of degree d needs d + 1 distinct ages in every
            # region; otherwise its coefficients are not identified.
            results[kind] = {
                "beta": beta,
                "df": int(rank),
                "identified": int(rank) == matrix.shape[1],
            }
        return results

    def predict_model(grid, kind: int, fit: dict, degree: int, knots) -> np.ndarray:
        """Evaluate a fitted model 1-5 at new ages."""
        return design_matrix(grid, degree, knots, kind) @ fit["beta"]

    return (
        HIGH,
        LOW,
        design_matrix,
        fit_models,
        predict_model,
        quantile_knots,
        scale,
    )


@app.cell
def smoothing_helpers(np):
    def make_smoother(x, y):
        """Prepare an exact cubic smoothing spline for data with repeated ages.

        Minimises sum_i (y_i - f(x_i))^2 + lambda * integral f''(t)^2 dt, with age in
        years. People with the same age share one fitted value, so the problem is
        solved on the distinct ages t with weights w (number of people) and mean
        heights ybar: (W + lambda K) g = W ybar, where K = Q R^-1 Q' is the natural
        cubic roughness matrix. This has the same solution as the problem on the
        individual observations. It is diagonalised once so lambda changes are cheap.
        """
        t, inverse, w = np.unique(x, return_inverse=True, return_counts=True)
        ybar = np.bincount(inverse, weights=y) / w
        h = np.diff(t)
        n = len(t)
        q = np.zeros((n, n - 2))
        j = np.arange(n - 2)
        q[j, j], q[j + 1, j], q[j + 2, j] = (
            1 / h[:-1],
            -1 / h[:-1] - 1 / h[1:],
            1 / h[1:],
        )
        r = (
            np.diag((h[:-1] + h[1:]) / 3)
            + np.diag(h[1:-1] / 6, 1)
            + np.diag(h[1:-1] / 6, -1)
        )
        second_map = np.linalg.solve(r, q.T)
        roughness = q @ second_map
        root_w = np.sqrt(w)
        eigenvalues, vectors = np.linalg.eigh(roughness / np.outer(root_w, root_w))
        eigenvalues = np.maximum(eigenvalues, 0.0)
        # Constants and straight lines have zero curvature: two zero eigenvalues.
        eigenvalues[:2] = 0.0
        projected = vectors.T @ (root_w * ybar)

        def smooth_fit(lam: float) -> dict:
            """Fitted values at the distinct ages for one value of lambda."""
            shrink = 1.0 / (1.0 + lam * eigenvalues)
            fitted = (vectors @ (shrink * projected)) / root_w
            second = np.r_[0.0, second_map @ fitted, 0.0]
            return {
                "t": t,
                "values": fitted,
                "second": second,
                "df": float(shrink.sum()),
            }

        def lambda_for_df(target: float) -> float:
            """Find lambda whose effective degrees of freedom equal a target (bisection)."""
            lo, hi = -8.0, 12.0
            for _ in range(80):
                mid = (lo + hi) / 2
                df = float(np.sum(1.0 / (1.0 + 10**mid * eigenvalues)))
                lo, hi = (mid, hi) if df > target else (lo, mid)
            return 10 ** ((lo + hi) / 2)

        return smooth_fit, lambda_for_df

    def predict_smoother(x, fit: dict):
        """Natural cubic spline through the fitted values, straight beyond 2 and 80."""
        x = np.asarray(x, dtype=float)
        t, values, second = fit["t"], fit["values"], fit["second"]
        i = np.clip(np.searchsorted(t, x, side="right") - 1, 0, len(t) - 2)
        h = t[i + 1] - t[i]
        a, b = (t[i + 1] - x) / h, (x - t[i]) / h
        pred = (
            a * values[i]
            + b * values[i + 1]
            + ((a**3 - a) * second[i] + (b**3 - b) * second[i + 1]) * h**2 / 6
        )
        left_h, right_h = t[1] - t[0], t[-1] - t[-2]
        left_slope = (values[1] - values[0]) / left_h - left_h * second[1] / 6
        right_slope = (values[-1] - values[-2]) / right_h + right_h * second[-2] / 6
        pred = np.where(x < t[0], values[0] + left_slope * (x - t[0]), pred)
        return np.where(x > t[-1], values[-1] + right_slope * (x - t[-1]), pred)

    return make_smoother, predict_smoother


@app.cell
def smoother_setup(ages, heights, make_smoother, np):
    smoother, lambda_for_df = make_smoother(ages, heights)
    # Slider positions: lambda values that give these effective df (rounded).
    _targets = [2.05, 3, 4, 5, 6, 8, 10, 13, 16, 20, 25, 30, 40, 50, 60, 70]
    lambda_steps = [0.0] + sorted(float(f"{lambda_for_df(_t):.2g}") for _t in _targets)
    n_distinct = len(np.unique(ages))
    return lambda_for_df, lambda_steps, n_distinct, smoother


@app.cell
def controls(lambda_for_df, lambda_steps, mo):
    model_names = [
        "1. Polynomial",
        "2. Piecewise: per region",
        "3. Piecewise: adjustments",
        "4. Regression spline",
        "5. Natural spline",
        "6. Smoothing spline",
    ]
    degree = mo.ui.slider(
        0,
        3,
        value=3,
        step=1,
        show_value=True,
        label="Polynomial degree d",
        full_width=True,
    )
    knot_count = mo.ui.slider(
        1,
        6,
        value=2,
        step=1,
        show_value=True,
        label="Number of interior knots K",
        full_width=True,
    )
    _default = min(lambda_steps, key=lambda v: abs(v - lambda_for_df(8)))
    smoothness = mo.ui.slider(
        steps=lambda_steps,
        value=_default,
        show_value=True,
        label="Smoothness λ",
        full_width=True,
    )
    view = mo.ui.dropdown(
        ["All six"] + model_names, value="All six", label="Show", full_width=True
    )
    tails = mo.ui.checkbox(value=True, label="Show extrapolation (ages 0–2 and 80–100)")
    return degree, knot_count, model_names, smoothness, tails, view


@app.cell
def sidebar(degree, knot_count, mo, smoothness, tails, view):
    mo.sidebar(
        [
            mo.md("### Change the fit"),
            view,
            degree,
            mo.md("**0** constant · **1** line  \n**2** quadratic · **3** cubic"),
            knot_count,
            mo.md(
                "Knots at equally spaced **quantiles of age**, as `bs()` and `ns()` do."
            ),
            smoothness,
            tails,
            mo.md(
                "**Degree:** plots 1–4; plot 5 needs d = 3.\n\n**Knots:** plots 2–5.\n\n"
                "**λ:** plot 6 only. Larger values make bending more expensive. "
                "Plot 6 is always cubic."
            ),
            mo.md(
                "---\n**Try this**\n\n"
                "1. Degree **1**: compare jumps and corners.\n"
                "2. Degree **3**: compare smooth joins.\n"
                "3. Add knots: plots 2 and 3 still match.\n"
                "4. Look at the tails of plots 4–6 before age 2 and after 80.\n"
                "5. Increase λ: plot 6 approaches a straight line.\n"
                "6. Scroll down: which settings predict new people best?"
            ),
        ],
        width="270px",
    )
    return


