@app.cell
def fitted_models(
    ages, degree, fit_models, heights, knot_count, quantile_knots, smoother, smoothness
):
    knots = quantile_knots(ages, knot_count.value)
    fits = fit_models(ages, heights, degree.value, knots)
    fits[5] = smoother(smoothness.value)
    return fits, knots


@app.cell
def explanations():
    def explain_fit(kind: int, degree: int, count: int) -> tuple[str, str, str]:
        """Map each formula to the columns and constraints that define it."""
        if kind == 0:
            return (
                "One polynomial covers all ages. A higher degree lets it bend, "
                "but every coefficient changes the curve everywhere.",
                r"$\hat f(x)=P_d(x)\,\beta$",
                "Design row: powers of age. One coefficient per power, including the constant.",
            )
        if kind == 1:
            return (
                "Each region gets its own polynomial; the curve can jump at the knots. "
                + (
                    "At degree 0, each level is the region's mean height."
                    if degree == 0
                    else ""
                ),
                r"$\hat f(x)=\sum_{r=0}^{K} I_r(x)\,P_d(x)\,\beta_r$",
                "Design row: one block of powers per region. Only the block of the "
                "person's own region is nonzero.",
            )
        if kind == 2:
            return (
                "The fit is identical to plot 2. Start with the first region's polynomial, "
                "then add a polynomial adjustment after each knot.",
                r"$\hat f(x)=P_d(x)\beta+\sum_{k=1}^{K}I(x\geq c_k)P_d(x)\delta_k$",
                "Design row: baseline powers + powers switched on after each knot. "
                "The adjustments add up; their constant terms still allow jumps. "
                "Gold and raspberry show the first adjustment just after the first knot.",
            )
        if kind == 3:
            if degree == 0:
                return (
                    "A degree-0 spline would be a step function forced to be continuous, "
                    "which is just a constant. Start at degree 1. The step functions are "
                    "in plots 2 and 3.",
                    "**Choose degree 1, 2 or 3.**",
                    "",
                )
            join = {
                1: "Heights match at the knots; slopes may differ, so corners are allowed.",
                2: "Heights and slopes match; curvature may change.",
                3: "Heights, slopes and curvatures match at every knot.",
            }[degree]
            return (
                join + " Beyond 2 and 80 the last polynomial piece simply continues.",
                r"$\hat f(x)=P_d(x)\beta+\sum_{k=1}^{K}\gamma_k(x-c_k)_+^d$",
                "Design row: powers + one hinge column per knot. The hinge is zero "
                "before its knot, which forces the pieces to join.",
            )
        if kind == 4:
            if degree != 3:
                return (
                    "Natural splines are defined only for odd degrees, and in practice "
                    "(ISLR, R's ns()) only the cubic one is used. For d = 0 and d = 2 they "
                    "are not defined. For d = 1 the natural linear spline is plot 4 with "
                    "flat tails: it adds no constraint inside the data. Set d = 3.",
                    "**Set d = 3.**",
                    "",
                )
            return (
                "A cubic spline that continues as a straight line before age 2 and after "
                "age 80. Straight tails that join smoothly need zero curvature at 2 and 80. "
                "These two extra constraints remove two coefficients and also change the "
                "fit inside the data. This is R's ns().",
                r"$\hat f(x)=P_3(x)\beta+\sum_{k}\gamma_k(x-c_k)_+^3$ with "
                r"$f''(2)=f''(80)=0$, straight outside $[2,80]$",
                f"Same columns as plot 4, combined so that the curvature is zero at both "
                f"boundaries: K + 4 − 2 = {count + 2} coefficients.",
            )
        return (
            "A cubic spline with a knot at every distinct age. Keep all those knots; "
            "control flexibility with λ. At λ = 0 it goes through the mean height at "
            "each age. As λ grows, it approaches the least-squares straight line.",
            r"$\min_f\;\underbrace{\sum_i\{y_i-f(x_i)\}^2}_{\text{fit the data}}"
            r"+\lambda\underbrace{\int f''(t)^2\,dt}_{\text{penalise bending}}$",
            "Effective df measures the flexibility left after the penalty, not the "
            "number of knots. People with the same age share one fitted value, so "
            "the maximum is the number of distinct ages.",
        )

    return (explain_fit,)


@app.cell
def plot_helpers(colours, design_matrix, np, plt, predict_model, predict_smoother):
    Y_LIMITS = (60.0, 215.0)

    def curve(grid, kind: int, fit: dict, settings: dict):
        """Predictions of any of the six models at new ages."""
        if kind == 5:
            return predict_smoother(grid, fit)
        return predict_model(grid, kind, fit, settings["degree"], settings["knots"])

    def draw_fit(kind: int, fit, settings: dict, sample: tuple):
        """One panel: data, fitted curve, knots, jumps and extrapolation zones."""
        x, y = sample
        degree, knots = settings["degree"], settings["knots"]
        low, high = (0.0, 100.0) if settings["tails"] else (2.0, 80.0)
        fig, ax = plt.subplots(figsize=(4.6, 3.0), layout="constrained")
        if fit is None or not fit.get("identified", True):
            if fit is not None:
                message = (
                    "Not identified: a region has\nfewer than d + 1 distinct ages.\n\n"
                    "Use fewer knots or a lower degree"
                )
            elif kind == 4:
                message = "Natural splines: d = 3 only\n\nNot defined for d = 0 or 2"
            else:
                message = "Degree 0: unavailable\n\nChoose degree 1–3"
            ax.text(
                0.5,
                0.53,
                message,
                ha="center",
                va="center",
                transform=ax.transAxes,
                fontsize=13,
                color="#66727c",
            )
            ax.set_axis_off()
            plt.close(fig)
            return fig
        ax.scatter(x, y, s=10, color=colours["grey"], alpha=0.5, edgecolors="none")
        if settings["tails"]:
            for a, b in ((0.0, 2.0), (80.0, 100.0)):
                ax.axvspan(a, b, color="#f3ead3", alpha=0.8, zorder=0)
        if kind in (1, 2, 3, 4):
            for knot in knots:
                ax.axvline(knot, color="#8b939b", linestyle=":", linewidth=1)
        if kind in (4, 5):
            for boundary in (2, 80):
                ax.axvline(boundary, color="#b07b38", linestyle="--", linewidth=1)
        edges = np.r_[low, knots, high] if kind in (1, 2) else np.array([low, high])
        for a, b in zip(edges[:-1], edges[1:]):
            grid = np.linspace(a, b - 1e-7, 240)
            ax.plot(
                grid,
                curve(grid, kind, fit, settings),
                color=colours["purple"],
                lw=2,
                zorder=4,
            )
        if kind in (1, 2):
            for knot in knots:
                join = curve(np.array([knot - 1e-7, knot]), kind, fit, settings)
                for j, fill in enumerate(("white", colours["purple"])):
                    ax.plot(
                        knot,
                        join[j],
                        "o",
                        color=colours["purple"],
                        markerfacecolor=fill,
                        ms=4,
                        zorder=5,
                    )
        if kind == 2:
            next_edge = knots[1] if len(knots) > 1 else 80.0
            grid = np.linspace(knots[0], knots[0] + 0.45 * (next_edge - knots[0]), 50)
            base = design_matrix(grid, degree, knots, 0) @ fit["beta"][: degree + 1]
            ax.plot(grid, base, "--", color=colours["gold"], lw=1.8, label="Baseline")
            end = curve(grid[-1:], kind, fit, settings)
            ax.vlines(
                grid[-1],
                base[-1],
                end[0],
                color=colours["raspberry"],
                lw=2,
                label="Adjustment",
            )
            ax.legend(loc="lower right", fontsize=8, frameon=True)
        ax.set(
            xlim=(low, high), ylim=Y_LIMITS, xlabel="Age (years)", ylabel="Height (cm)"
        )
        plt.close(fig)
        return fig

    return (draw_fit,)


@app.cell
def gallery(
    ages,
    degree,
    draw_fit,
    explain_fit,
    fits,
    heights,
    knot_count,
    knots,
    mo,
    model_names,
    n_distinct,
    tails,
    view,
):
    _settings = {"degree": degree.value, "knots": knots, "tails": tails.value}
    _selected = range(6) if view.value == "All six" else [model_names.index(view.value)]
    _cards = []
    for _kind in _selected:
        _fit = fits[_kind]
        _text, _formula, _columns = explain_fit(_kind, degree.value, len(knots))
        _fig = draw_fit(_kind, _fit, _settings, (ages, heights))
        if _kind == 5:
            _df = f"{_fit['df']:.1f} effective df · {n_distinct} knots"
        elif _fit and not _fit["identified"]:
            _df = "Coefficients not identified"
        elif _fit:
            _df = f"{_fit['df']} fitted coefficient" + ("s" if _fit["df"] != 1 else "")
        else:
            _df = "Requires degree ≥ 1"
        _card = mo.vstack(
            [
                mo.md(f"### {model_names[_kind]}\n\n**{_df}**"),
                mo.as_html(_fig),
                mo.md(_text),
                mo.md(_formula),
                mo.md(_columns),
            ]
        )
        _cards.append(f'<section class="fit-card">{_card.text}</section>')
    _legend = (
        "**Grey dots:** individual people · **Purple line:** fitted curve · "
        "**Grey dotted vertical lines:** interior knots · "
        "**Brown dashed vertical lines:** boundary knots at ages 2 and 80 "
        "(natural and smoothing splines)."
    )
    if tails.value:
        _legend += " **Shaded areas:** extrapolation beyond the observed ages."
    _class = (
        'class="fit-grid"'
        if view.value == "All six"
        else 'style="max-width:760px;margin:auto"'
    )
    mo.vstack(
        [
            mo.md(_legend),
            mo.Html(f"<div {_class}>" + "".join(_cards) + "</div>"),
        ]
    ).style({"max-width": "1500px", "margin": "auto"})
    return


@app.cell
def flexibility_curves(
    ages,
    degree,
    design_matrix,
    heights,
    lambda_for_df,
    np,
    predict_smoother,
    quantile_knots,
    smoother,
    test_ages,
    test_heights,
):
    def _rmse(observed, predicted):
        return float(np.sqrt(np.mean((observed - predicted) ** 2)))

    def _scores(kind: int, d: int, knots):
        """Coefficients, training RMSE and validation RMSE of one model; None if not identified."""
        train_x = design_matrix(ages, d, knots, kind)
        beta, _, rank, _ = np.linalg.lstsq(train_x, heights, rcond=None)
        if rank < train_x.shape[1]:
            return None
        test_x = design_matrix(test_ages, d, knots, kind)
        return (
            int(rank),
            _rmse(heights, train_x @ beta),
            _rmse(test_heights, test_x @ beta),
        )

    _d = degree.value
    curves = {}
    # 1. Polynomial: degree 0 to 12. Chebyshev columns span the same polynomials as
    # powers of age but avoid numerical problems at high degree.
    _u = (ages - 41.0) / 39.0
    _tu = (test_ages - 41.0) / 39.0
    _rows = []
    for _deg in range(13):
        _X = np.polynomial.chebyshev.chebvander(_u, _deg)
        _beta = np.linalg.lstsq(_X, heights, rcond=None)[0]
        _T = np.polynomial.chebyshev.chebvander(_tu, _deg)
        _rows.append(
            (
                _deg,
                _deg + 1,
                _rmse(heights, _X @ _beta),
                _rmse(test_heights, _T @ _beta),
            )
        )
    curves[0] = _rows
    # 2-3. Piecewise polynomials of the current degree (both parameterisations are identical).
    _rows = []
    for _k in range(0, 13):
        _score = _scores(1, _d, quantile_knots(ages, _k))
        if _score is None:
            break  # from here on some region has fewer than d + 1 distinct ages
        _rows.append((_k, *_score))
    curves[1] = _rows
    # 4-5. Regression and natural splines of the current degree, 0 to 20 knots.
    for _kind in (3, 4):
        _rows = []
        if (_kind == 3 and _d > 0) or (_kind == 4 and _d == 3):
            for _k in range(0, 21):
                _score = _scores(_kind, _d, quantile_knots(ages, _k))
                if _score is None:
                    break
                _rows.append((_k, *_score))
        curves[_kind] = _rows
    # 6. Smoothing spline over a grid of lambda values.
    _rows = []
    for _target in np.geomspace(2.05, 76, 32):
        _lam = lambda_for_df(float(_target))
        _fit = smoother(_lam)
        _rows.append(
            (
                _lam,
                _fit["df"],
                _rmse(heights, predict_smoother(ages, _fit)),
                _rmse(test_heights, predict_smoother(test_ages, _fit)),
            )
        )
    curves[5] = _rows
    return (curves,)


@app.cell
def flexibility_section(
    ages,
    colours,
    curves,
    degree,
    fits,
    heights,
    knot_count,
    mo,
    np,
    plt,
    predict_smoother,
    smoothness,
    test_ages,
    test_heights,
):
    _labels = {
        0: "1. Polynomial (degree 0–12)",
        1: f"2–3. Piecewise, d = {degree.value} (identical fits)",
        3: f"4. Regression spline, d = {degree.value}",
        4: "5. Natural cubic spline",
        5: "6. Smoothing spline (λ)",
    }
    _styles = {
        0: (colours["purple"], "-"),
        1: (colours["petrol"], "-"),
        3: (colours["gold"], "-"),
        4: (colours["raspberry"], "-"),
        5: ("#333333", "--"),
    }
    # Current slider setting of each model: (setting, coefficients) to mark.
    _current = {
        0: degree.value,
        1: knot_count.value,
        3: knot_count.value,
        4: knot_count.value,
    }

    def _rmse(observed, predicted):
        return float(np.sqrt(np.mean((observed - predicted) ** 2)))

    _fig, _axes = plt.subplots(
        1, 2, figsize=(11.5, 4.2), sharey=True, layout="constrained"
    )
    _best_rows = []
    for _kind in (0, 1, 3, 4, 5):
        _rows = curves[_kind]
        if not _rows:
            continue
        _setting, _df, _train, _test = map(np.array, zip(*_rows))
        _colour, _ls = _styles[_kind]
        for _ax, _y in zip(_axes, (_train, _test)):
            _ax.plot(
                _df,
                _y,
                _ls,
                color=_colour,
                lw=1.8,
                marker="o",
                ms=2.5,
                label=_labels[_kind],
            )
        # Mark the current setting.
        if _kind == 5:
            _fit = fits[5]
            _mark = (
                _fit["df"],
                _rmse(heights, predict_smoother(ages, _fit)),
                _rmse(test_heights, predict_smoother(test_ages, _fit)),
            )
        else:
            _match = [r for r in _rows if r[0] == _current[_kind]]
            _mark = (_match[0][1], _match[0][2], _match[0][3]) if _match else None
        if _mark:
            for _ax, _y in zip(_axes, _mark[1:]):
                _ax.plot(
                    _mark[0],
                    _y,
                    "o",
                    ms=9,
                    markerfacecolor="white",
                    markeredgecolor=_colour,
                    markeredgewidth=2,
                    zorder=6,
                )
        _i = int(np.argmin(_test))
        _axes[1].plot(_df[_i], _test[_i], "*", ms=13, color=_colour, zorder=7)
        _what = {0: "degree", 1: "knots K", 3: "knots K", 4: "knots K", 5: "λ"}[_kind]
        _value = f"{_setting[_i]:.2g}" if _kind == 5 else f"{int(_setting[_i])}"
        _best_rows.append(
            f"| {_labels[_kind]} | {_what} = {_value} | {_df[_i]:.1f} | "
            f"{_train[_i]:.2f} | {_test[_i]:.2f} |"
        )
    for _ax, _title in zip(
        _axes,
        (
            "Training loss: the 300 people used for fitting",
            "Validation loss: 3,607 people not used for fitting",
        ),
    ):
        _ax.set_xscale("log")
        _ax.set_xticks([1, 2, 5, 10, 20, 50])
        _ax.set_xticklabels(["1", "2", "5", "10", "20", "50"])
        _ax.set(
            xlabel="Number of coefficients (effective df for plot 6)",
            title=_title,
            ylim=(8.8, 12.0),
        )
        _ax.title.set_fontsize(10.5)
    _axes[0].set_ylabel("RMSE (cm)")
    _axes[0].legend(fontsize=8, loc="upper right", frameon=True)
    plt.close(_fig)

    mo.vstack(
        [
            mo.md(
                """
        ## Choosing K and λ: training loss against validation loss

        Each line is one model from above, fitted with more and more flexibility:
        a higher polynomial degree, more knots, or a smaller λ. The degree slider sets
        d for plots 2–5. **Open circles** mark the current slider settings; **stars**
        mark the lowest validation loss for each model. The y-axis starts at 8.8 cm, so the
        stiffest models (a line has RMSE above 19 cm) are above the plot. Quantile knots
        move when K changes, so the training loss of a spline can go up slightly.
        """
            ),
            mo.as_html(_fig),
            mo.md(
                "| Model | Best setting on the validation set | Coefficients / edf | Training RMSE | Validation RMSE |\n"
                "|:--|:--|--:|--:|--:|\n" + "\n".join(_best_rows)
            ),
            mo.md(
                """
        Training loss keeps falling as a model gets more coefficients. Validation loss
        falls while the extra flexibility captures the pattern and rises once it starts
        following noise in the 300 training people. **Use validation loss to compare
        settings:** training loss alone rewards flexibility. For a real analysis,
        cross-validation on the training data can also guide the choice of degree,
        K or λ.
        """
            ),
        ]
    ).style({"max-width": "1500px", "margin": "auto"})
    return


